ValidationRule.errorConditionFormula:
AND(
NOT( VR_Status_Automation_Bypass__c ),
$Profile.Name <> "System Administrator",
ISCHANGED(Status__c),


OR(

/* Developer restrictions */
AND(
$UserRole.Name = "Developer",
OR(
ISPICKVAL(Status__c,"Approved"),
ISPICKVAL(Status__c,"Rejected")
)
),

/* QA restrictions */
AND(
$UserRole.Name = "QA Engineer",
OR(

ISPICKVAL(Status__c,"Approved"),
ISPICKVAL(Status__c,"Rejected")

)
),

/* Release Manager restrictions */
AND(
$UserRole.Name = "Release Manager",
OR(
ISPICKVAL(Status__c,"Draft"),
ISPICKVAL(Status__c,"Submitted")

)
)

)

)
